import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # --- Totals ---
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if df['Revenue_LY'].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(total_rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": float(total_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": float(total_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": float(total_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": float(total_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    if total_rev_lw and total_rev_lw != 0:
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly and total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # --- Top 5 entities by Revenue_TW ---
    top5 = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top5.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(to_float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": round(to_float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })
        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": row['Entity'], "metric": "rank", "period": "TW",
                "value": to_float(row['Rank']),
                "formula": "Rank"
            })

    # --- Top WoW gainers/losers ---
    wow_df = df.dropna(subset=['Revenue_TW', 'Revenue_LW'])
    wow_df = wow_df[wow_df['Revenue_LW'] > 0].copy()
    wow_df['wow_calc'] = (wow_df['Revenue_TW'] - wow_df['Revenue_LW']) / wow_df['Revenue_LW'] * 100

    top_gainers = wow_df.sort_values('wow_calc', ascending=False).head(3)
    for _, row in top_gainers.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(row['wow_calc']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    top_losers = wow_df.sort_values('wow_calc', ascending=True).head(3)
    for _, row in top_losers.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(row['wow_calc']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # --- Top YoY gainers/losers ---
    yoy_df = df.dropna(subset=['Revenue_TW', 'Revenue_LY'])
    yoy_df = yoy_df[yoy_df['Revenue_LY'] > 0].copy()
    yoy_df['yoy_calc'] = (yoy_df['Revenue_TW'] - yoy_df['Revenue_LY']) / yoy_df['Revenue_LY'] * 100

    if not yoy_df.empty:
        top_yoy_gainers = yoy_df.sort_values('yoy_calc', ascending=False).head(2)
        for _, row in top_yoy_gainers.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(float(row['yoy_calc']), 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

        top_yoy_losers = yoy_df.sort_values('yoy_calc', ascending=True).head(2)
        for _, row in top_yoy_losers.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(float(row['yoy_calc']), 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # --- Top entity by units and orders ---
    units_df = df.dropna(subset=['Units_TW'])
    if not units_df.empty:
        top_units = units_df.sort_values('Units_TW', ascending=False).iloc[0]
        facts.append({
            "entity": top_units['Entity'], "metric": "units", "period": "TW",
            "value": float(top_units['Units_TW']),
            "formula": "max(Units_TW)"
        })

    orders_df = df.dropna(subset=['Orders_TW'])
    if not orders_df.empty:
        top_orders = orders_df.sort_values('Orders_TW', ascending=False).iloc[0]
        facts.append({
            "entity": top_orders['Entity'], "metric": "orders", "period": "TW",
            "value": float(top_orders['Orders_TW']),
            "formula": "max(Orders_TW)"
        })

    # Limit to 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
